import itertools
e=df['eps'].values;T_=df['T'].values;s=df['sigma'].values
Tb={'T':T_,'T2':T_**2,'lnT':np.log(T_),'1/T':1/T_,'sqrtT':np.sqrt(T_),'T3':T_**3,'expT':np.exp(T_),'1/T2':1/T_**2}
Eb={'e':e,'e2':e**2,'sqrte':np.sqrt(e),'e3':e**3,'lne':np.log(e),'e1.5':e**1.5}
res=[]
names=list(Tb); enames=list(Eb)
for k in [1,2]:
  for tc in itertools.combinations(names,k):
    for ec in itertools.combinations(enames,2):
        cols=[np.ones_like(e)]+[Tb[t] for t in tc]+[Eb[x] for x in ec]+[Tb[t]*Eb[ec[0]] for t in tc]
        A=np.column_stack(cols)
        c,_,_,_=np.linalg.lstsq(A,s,rcond=None)
        r=s-A@c
        res.append((np.mean(r**2)/np.var(s),tc,ec))
res.sort(key=lambda x:x[0])
for r_ in res[:8]: print(r_)
